@layer components {
  /* Command: ui-sdk's stylesheet draws the search field over the list. The ViteHub palette floats with no border. */
  [data-slot="command"] {
    background: var(--vh-bg);
    border-radius: var(--vh-radius);
    box-shadow: 0 0 0 1px var(--vh-border);
    border: 0;
  }

  [data-slot="command-input-wrapper"] {
    align-items: center;
    border-bottom: 1px solid var(--vh-border);
    color: var(--vh-muted);
    display: flex;
    gap: 0.5rem;
    height: 2.75rem;
    padding-inline: 0.75rem;
  }

  [data-slot="command-input-wrapper"] > svg {
    flex: none;
    height: 1rem;
    width: 1rem;
  }

  [data-slot="command-input-wrapper"] > [data-slot="command-input"] {
    border-bottom: 0;
    color: var(--vh-text);
    height: 100%;
    padding-inline: 0;
  }

  [data-slot="command-item"] > svg {
    color: var(--vh-muted);
  }

  [data-slot="dialog-content"][data-command-dialog] {
    background: var(--vh-popover);
    backdrop-filter: blur(12px);
    border-radius: calc(var(--vh-radius) * 1.5);
    box-shadow: var(--vh-shadow-dialog);
    color: var(--vh-text);
    height: fit-content;
    inset: 0;
    margin: 12dvh auto auto;
    max-height: calc(100dvh - 2rem);
    outline: none;
    overflow: hidden;
    padding: 0;
    position: fixed;
    width: min(32rem, calc(100% - 2rem));
    z-index: 50;
  }

  :is([data-slot="command-dialog-title"], [data-slot="command-dialog-description"]) {
    clip-path: inset(50%);
    height: 1px;
    overflow: hidden;
    position: absolute;
    white-space: nowrap;
    width: 1px;
  }

  [data-slot="dialog-content"][data-command-dialog] > [data-slot="command"] {
    background: transparent;
    box-shadow: none;
    width: 100%;
  }
}

export { default as Command } from "./Command.vue";
export { default as CommandDialog } from "./CommandDialog.vue";
export { default as CommandEmpty } from "./CommandEmpty.vue";
export { default as CommandGroup } from "./CommandGroup.vue";
export { default as CommandInput } from "./CommandInput.vue";
export { default as CommandItem } from "./CommandItem.vue";
export { default as CommandList } from "./CommandList.vue";
export { default as CommandSeparator } from "./CommandSeparator.vue";
export { default as CommandShortcut } from "./CommandShortcut.vue";
export type * from "./types.ts";

export interface CommandProps {
  query?: string;
  defaultQuery?: string;
}

export interface CommandEmits {
  "update:query": [query: string];
  action: [event: { value: string }];
}

export interface CommandInputProps {
  label?: string;
  placeholder?: string;
}

export interface CommandInputSlots {
  icon?: () => unknown;
}

export interface CommandEmptyProps {
  label?: string;
}

export interface CommandGroupProps {
  heading?: string;
}

export interface CommandItemProps {
  value: string;
  disabled?: boolean;
  shortcut?: string;
}

export interface CommandDialogProps {
  open?: boolean;
  defaultOpen?: boolean;
  title?: string;
  description?: string;
}

export interface CommandDialogEmits {
  "update:open": [open: boolean];
  action: [event: { value: string }];
}

export interface CommandDialogSlots {
  default?: () => unknown;
  trigger?: () => unknown;
}

export interface CommandSlots {
  default?: () => unknown;
}

export interface CommandListSlots {
  default?: () => unknown;
}

export interface CommandEmptySlots {
  default?: () => unknown;
}

export interface CommandGroupSlots {
  default?: () => unknown;
}

export interface CommandItemSlots {
  default?: () => unknown;
}

export interface CommandShortcutSlots {
  default?: () => unknown;
}
